def normalize_newlines(text: str) -> str:
    """
    Replace multiple consecutive newline characters with a single newline.
    
    Args:
        text (str): Input string with multiple newlines.
    
    Returns:
        str: Normalized string with single newlines.
    """
    lines = text.split("\n")  # Split by newlines
    filtered_lines = [line for line in lines if line.strip() or line == ""]  # Keep empty lines
    return "\n".join(filtered_lines)  # Join with a single newline

